use console;
use math;

main() {
    math.Complex z = math.Complex(3, 4);
    math.Complex w = math.polar(2, math.pi / 2);   // 2i

    console.writeln(z + w, "  ", z * w, "  ", z / w);   // 3 + 6i  -8 + 6i  2 - 1.5i
    console.writeln(2 * z, "  ", -z, "  ", z.conjugate()); // 6 + 8i  -3 - 4i  3 - 4i
    console.writeln(z.abs(), " ", z.arg());              // 5 0.92729522
    console.writeln(z.sqrt(), "  ", z.pow(2));           // 2 + i  -7 + 24i

    // Все корни: x³ = -8
    console.writeln(math.Complex(-8).roots(3));          // [1 + 1.73205081i, -2, 1 - 1.73205081i]

    // Тождество Эйлера
    math.Complex euler = math.Complex(0, math.pi).exp();
    console.writeln(euler, " ", euler.is_close(-1));    // -1 true
}

